// QA-only embedded illustration bytes.
const images={
 home:'',
 find:'',
 backup:'',
} as const;
export const qaIllustrationBytes=(name:string):Uint8Array=>{if(!(name in images))throw Error("Unknown QA illustration");return Uint8Array.from(atob(images[name as keyof typeof images]),c=>c.charCodeAt(0));};
